insert into levels (id, title, sort) values ('foundations', 'Foundations', 1) on conflict (id) do nothing;
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('pillars', 'foundations', 'The Five Pillars', 'What Islam is built on', '#2F7D5B', true, 1) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-1', 'pillars', 'Built on five', 'The Prophet ﷺ said that Islam is built on five: the testimony of faith (shahada), prayer (salah), charity (zakat), fasting in Ramadan (sawm) and pilgrimage to the House (hajj).', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'choice', '{"type":"choice","prompt":"How many pillars is Islam built on?","options":["Three","Five","Six","Seven"],"answer":1,"explain":"Islam is built on five pillars.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8, Sahih Muslim 16"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'match', '{"type":"match","prompt":"Match each pillar to its meaning","pairs":[["Shahada","Testimony of faith"],["Salah","Prayer"],["Zakat","Obligatory charity"],["Sawm","Fasting"],["Hajj","Pilgrimage"]],"explain":"These five together are the pillars of Islam."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'choice', '{"type":"choice","prompt":"Which of these is NOT one of the five pillars?","options":["Fasting in Ramadan","Zakat","Reading the whole Quran each month","Hajj"],"answer":2,"explain":"Reading the Quran is highly rewarded, but the five pillars are shahada, salah, zakat, sawm and hajj."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'order', '{"type":"order","prompt":"Put the pillars in the order the hadith mentions them","items":["Shahada","Salah","Zakat","Hajj","Sawm"],"explain":"In the narration of Sahih al-Bukhari 8 the order is shahada, salah, zakat, hajj, then fasting in Ramadan. Other narrations mention fasting before hajj.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8"}}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'choice', '{"type":"choice","minLevel":"intermediate","prompt":"Which Companion narrated the hadith \"Islam is built on five\"?","options":["Abu Hurayrah","Abdullah ibn Umar","Anas ibn Malik","Aisha"],"answer":1,"explain":"It is narrated by Abdullah ibn Umar (may Allah be pleased with them both).","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8, Sahih Muslim 16"}}'::jsonb, 5);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-2', 'pillars', 'The shahada', 'The shahada is: "Ash-hadu an la ilaha illa Allah, wa ash-hadu anna Muhammadan rasul Allah." I bear witness that there is no god but Allah, and I bear witness that Muhammad is the Messenger of Allah.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'choice', '{"type":"choice","prompt":"What does \"la ilaha illa Allah\" mean?","options":["Allah is the greatest","There is no god but Allah","All praise is for Allah","In the name of Allah"],"answer":1,"explain":"\"La ilaha illa Allah\" means there is no god worthy of worship except Allah."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'order', '{"type":"order","prompt":"Build the shahada","items":["Ash-hadu","an la ilaha","illa Allah,","wa ash-hadu anna","Muhammadan","rasul Allah"],"explain":"This is the full testimony of faith."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'choice', '{"type":"choice","prompt":"The second part of the shahada is a testimony about whom?","options":["Prophet Ibrahim","Prophet Musa","Prophet Muhammad ﷺ","Angel Jibril"],"answer":2,"explain":"The second part bears witness that Muhammad ﷺ is the Messenger of Allah."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'match', '{"type":"match","prompt":"Match the Arabic to its meaning","pairs":[["Ash-hadu","I bear witness"],["La ilaha","There is no god"],["Illa Allah","Except Allah"],["Rasul","Messenger"]],"explain":"Knowing the meaning makes the words come alive."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-3', 'pillars', 'Salah and zakat', 'Muslims pray five times every day. Zakat is a yearly charity: 2.5% of savings that stay above a minimum amount (the nisab) for a full lunar year, given to those who are eligible.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"How many obligatory prayers are there each day?","options":["Three","Four","Five","Seven"],"answer":2,"explain":"There are five daily prayers: Fajr, Dhuhr, Asr, Maghrib and Isha."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'order', '{"type":"order","prompt":"Put the daily prayers in order, starting at dawn","items":["Fajr","Dhuhr","Asr","Maghrib","Isha"],"explain":"Fajr is at dawn, Dhuhr after midday, Asr in the afternoon, Maghrib at sunset and Isha at night."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"What share of eligible savings is paid as zakat?","options":["1%","2.5%","10%","20%"],"answer":1,"explain":"Zakat on savings is 2.5% once they stay above the nisab for a lunar year."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"In the Quran, which pillar is very often mentioned together with prayer?","options":["Hajj","Zakat","Fasting","Shahada"],"answer":1,"explain":"Allah often says \"establish prayer and give zakat\", for example in Al-Baqarah 2:43.","source":{"kind":"quran","reference":"Quran 2:43"}}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","minLevel":"advanced","prompt":"Over what period must savings stay above the nisab before zakat is due?","options":["One month","One lunar year (hawl)","Ramadan only","Five years"],"answer":1,"explain":"Zakat on wealth is due once it has stayed at or above the nisab for a full lunar year, called the hawl."}'::jsonb, 5);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-4', 'pillars', 'Fasting and hajj', 'In Ramadan, Muslims fast from dawn (Fajr) until sunset (Maghrib), leaving food, drink and marital relations. Hajj is the pilgrimage to Makkah, required once in a lifetime for those who are able.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"A fast in Ramadan lasts from…","options":["Sunrise to noon","Dawn to sunset","Midnight to midnight","Sunset to dawn"],"answer":1,"explain":"The fast begins at dawn (Fajr) and ends at sunset (Maghrib)."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"Why did Allah prescribe fasting, according to Al-Baqarah 2:183?","options":["To lose weight","So that you may attain taqwa","To save money","To travel"],"answer":1,"explain":"\"Fasting is prescribed for you… so that you may become mindful of Allah (taqwa).\"","source":{"kind":"quran","reference":"Quran 2:183"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"How often is hajj required?","options":["Every year","Every five years","Once in a lifetime, for those able","Never required"],"answer":2,"explain":"Hajj is an obligation once in a lifetime for those who are able to make the journey.","source":{"kind":"quran","reference":"Quran 3:97"}}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'match', '{"type":"match","prompt":"Match each pillar to when it happens","pairs":[["Sawm","The month of Ramadan"],["Hajj","The month of Dhul Hijjah"],["Salah","Five times every day"],["Zakat","Once a lunar year"]],"explain":"Each pillar has its own time."}'::jsonb, 4);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('prayer', 'foundations', 'How to Pray', 'Wudu and the steps of salah', '#2E6FA3', true, 2) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-1', 'prayer', 'Wudu', 'Wudu is the washing done before prayer. The Quran (5:6) commands washing the face, the arms up to the elbows, wiping the head, and washing the feet up to the ankles. The Sunnah adds rinsing the mouth and nose, and starting with the hands.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'order', '{"type":"order","prompt":"Put the steps of wudu in order","items":["Intention and Bismillah","Wash the hands","Rinse the mouth","Rinse the nose","Wash the face","Wash the arms to the elbows","Wipe the head and ears","Wash the feet to the ankles"],"explain":"This is the common order of wudu taught from the Sunnah.","source":{"kind":"quran","reference":"Quran 5:6"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'choice', '{"type":"choice","prompt":"Up to where are the arms washed in wudu?","options":["The wrists","The elbows","The shoulders","Only the fingers"],"answer":1,"explain":"The arms are washed up to and including the elbows.","source":{"kind":"quran","reference":"Quran 5:6"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'choice', '{"type":"choice","prompt":"Which part is wiped, not washed?","options":["The face","The feet","The head","The arms"],"answer":2,"explain":"The head is wiped with wet hands."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-2', 'prayer', 'Prayers and rak‘ahs', 'Each prayer is made of units called rak‘ahs. Fajr has 2, Dhuhr 4, Asr 4, Maghrib 3 and Isha 4. These are the obligatory (fard) rak‘ahs.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'match', '{"type":"match","prompt":"Match each prayer to its fard rak‘ahs","pairs":[["Fajr","2"],["Maghrib","3"],["Dhuhr","4"]],"explain":"Asr and Isha also have 4 fard rak‘ahs."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'choice', '{"type":"choice","prompt":"How many fard rak‘ahs does Maghrib have?","options":["2","3","4","5"],"answer":1,"explain":"Maghrib is the only daily prayer with 3 rak‘ahs."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'choice', '{"type":"choice","prompt":"How many fard rak‘ahs are there in a full day?","options":["15","17","19","20"],"answer":1,"explain":"2 + 4 + 4 + 3 + 4 = 17."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'choice', '{"type":"choice","minLevel":"intermediate","prompt":"Which two prayers may a traveller combine at the time of either one, in most schools?","options":["Fajr and Dhuhr","Dhuhr and Asr","Maghrib and Fajr","Asr and Maghrib"],"answer":1,"explain":"Dhuhr with Asr, and Maghrib with Isha, may be combined when travelling in the Shafi‘i, Maliki and Hanbali schools. The Hanafi school allows real combining only at Arafah and Muzdalifah during Hajj."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-3', 'prayer', 'Steps of a rak‘ah', 'A rak‘ah moves through standing, bowing (ruku‘), rising, prostrating (sujud), sitting, and prostrating again. The prayer opens with "Allahu Akbar" and ends with the tashahhud and the salam.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'order', '{"type":"order","prompt":"Put the first rak‘ah in order","items":["Takbir: \"Allahu Akbar\"","Recite Al-Fatihah","Ruku‘ (bow)","Stand up straight","First sujud","Sit briefly","Second sujud"],"explain":"This is the shape of every rak‘ah. A short surah is usually recited after Al-Fatihah in the first two rak‘ahs."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'choice', '{"type":"choice","prompt":"Which surah is recited in every rak‘ah?","options":["Al-Ikhlas","Al-Fatihah","An-Nas","Al-Kawthar"],"answer":1,"explain":"Al-Fatihah is recited in every rak‘ah of every prayer."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'choice', '{"type":"choice","prompt":"How does the prayer end?","options":["With a sujud","With the salam to the right and left","With ruku‘","By standing up"],"answer":1,"explain":"After the final tashahhud, the prayer ends with \"As-salamu alaykum wa rahmatullah\" to the right and left."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-4', 'prayer', 'What to say', 'In ruku‘ say "Subhana Rabbiya al-‘Azim" (Glory be to my Lord, the Magnificent). In sujud say "Subhana Rabbiya al-A‘la" (Glory be to my Lord, the Most High).', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'match', '{"type":"match","prompt":"Match each position to what is said","pairs":[["Opening","Allahu Akbar"],["Ruku‘","Subhana Rabbiya al-‘Azim"],["Sujud","Subhana Rabbiya al-A‘la"],["Ending","As-salamu alaykum wa rahmatullah"]],"explain":"These are the core words of each position.","source":{"kind":"hadith","reference":"Sahih Muslim 772"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'choice', '{"type":"choice","prompt":"What does \"Subhana Rabbiya al-A‘la\" mean?","options":["Allah is the greatest","Glory be to my Lord, the Most High","All praise is for Allah","Allah hears whoever praises Him"],"answer":1,"explain":"It is said in sujud, when we are lowest to the ground."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'choice', '{"type":"choice","prompt":"When rising from ruku‘, what is said?","options":["Sami‘a Allahu liman hamidah","Bismillah","Astaghfirullah","Subhan Allah"],"answer":0,"explain":"\"Allah hears whoever praises Him\", followed by \"Rabbana wa laka al-hamd\"."}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('seerah', 'foundations', 'The Seerah', 'The life of the Prophet ﷺ', '#1F7A8C', false, 3) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('seerah-1', 'seerah', 'Early life in Makkah', 'Muhammad ﷺ was born in Makkah in the Year of the Elephant, around 570 CE. He grew up an orphan and became known as al-Amin, the trustworthy.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('seerah-1', 'choice', '{"type":"choice","prompt":"What nickname did the people of Makkah give the Prophet ﷺ?","options":["As-Siddiq","Al-Amin","Al-Faruq","Saifullah"],"answer":1,"explain":"Al-Amin means the trustworthy. Even his enemies trusted him with their belongings."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('seerah-1', 'truefalse', '{"type":"truefalse","statement":"The Prophet ﷺ was raised by his father Abdullah.","answer":false,"explain":"His father died before he was born. He was raised by his grandfather Abd al-Muttalib and then his uncle Abu Talib."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('seerah-1', 'fill', '{"type":"fill","sentence":"The Prophet ﷺ was born in the Year of the ___.","options":["Elephant","Camel","Flood","Hijrah"],"answer":0,"explain":"It is named after the army with elephants that marched on Makkah that year (Surah Al-Fil).","source":{"kind":"quran","reference":"Quran 105"}}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('seerah-1', 'order', '{"type":"order","prompt":"Put these events in order","items":["Born in Makkah","His mother Aminah passes away","Raised by Abu Talib","Marries Khadijah"],"explain":"This is the order of his early life."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('seerah-2', 'seerah', 'The first revelation', 'At the age of 40, while in the cave of Hira, the angel Jibril came to the Prophet ﷺ and said "Iqra" (Read). The first verses revealed were the opening of Surah Al-Alaq.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('seerah-2', 'choice', '{"type":"choice","prompt":"In which cave did the first revelation come?","options":["Thawr","Hira","Uhud","Kahf"],"answer":1,"explain":"The first revelation came in the cave of Hira.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 3"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('seerah-2', 'fill', '{"type":"fill","sentence":"The first word Jibril said was \"___\", which means \"Read\".","options":["Iqra","Qul","Bismillah","Salam"],"answer":0,"explain":"Surah Al-Alaq begins: \"Read in the name of your Lord who created.\"","source":{"kind":"quran","reference":"Quran 96:1"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('seerah-2', 'truefalse', '{"type":"truefalse","statement":"Khadijah was the first person to believe in the Prophet ﷺ.","answer":true,"explain":"Khadijah was the first to believe in him and supported him with her wealth and comfort."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('seerah-2', 'choice', '{"type":"choice","prompt":"How old was the Prophet ﷺ when revelation began?","options":["25","33","40","53"],"answer":2,"explain":"He was 40 years old."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('seerah-3', 'seerah', 'The Hijrah', 'After 13 years of calling people to Islam in Makkah through hardship and persecution, the Prophet ﷺ migrated to Madinah with Abu Bakr in 622 CE. This journey is the Hijrah.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('seerah-3', 'choice', '{"type":"choice","prompt":"Who travelled with the Prophet ﷺ on the Hijrah?","options":["Umar","Abu Bakr","Uthman","Bilal"],"answer":1,"explain":"Abu Bakr as-Siddiq was his companion on the journey.","source":{"kind":"quran","reference":"Quran 9:40"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('seerah-3', 'truefalse', '{"type":"truefalse","statement":"They hid in the cave of Hira during the Hijrah.","answer":false,"explain":"They hid in the cave of Thawr. Hira is where the first revelation came."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('seerah-3', 'match', '{"type":"match","prompt":"Match each name to its role","pairs":[["Ansar","The people of Madinah who helped"],["Muhajirun","The Muslims who migrated"],["An-Najashi","King who protected Muslims in Abyssinia"]],"explain":"The Prophet ﷺ joined the Muhajirun and Ansar as brothers in Madinah."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('seerah-3', 'fill', '{"type":"fill","sentence":"The Islamic calendar starts from the year of the ___.","options":["Hijrah","Birth of the Prophet","First revelation","Conquest of Makkah"],"answer":0,"explain":"The Hijri calendar counts from the Hijrah, a decision made during the caliphate of Umar."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('seerah-4', 'seerah', 'Madinah and the final years', 'In Madinah the Prophet ﷺ built his masjid and a community. Makkah was opened in 8 AH with forgiveness, he performed the Farewell Hajj in 10 AH, and he passed away in 11 AH at the age of 63.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('seerah-4', 'order', '{"type":"order","prompt":"Put these events in order","items":["Building the masjid in Madinah","Battle of Badr","Opening of Makkah","Farewell Hajj"],"explain":"Masjid (1 AH), Badr (2 AH), Makkah (8 AH), Farewell Hajj (10 AH)."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('seerah-4', 'truefalse', '{"type":"truefalse","statement":"When the Prophet ﷺ entered Makkah, he forgave the people who had persecuted him.","answer":true,"explain":"He forgave them, showing mercy at the moment of victory."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('seerah-4', 'choice', '{"type":"choice","prompt":"How old was the Prophet ﷺ when he passed away?","options":["40","53","63","70"],"answer":2,"explain":"He passed away at 63, in 11 AH."}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('sahaba', 'foundations', 'The Companions', 'Stories of the Sahaba', '#5B7F2E', false, 4) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('sahaba-1', 'sahaba', 'Abu Bakr as-Siddiq', 'Abu Bakr was the Prophet’s closest friend, the first free adult man to accept Islam, his companion on the Hijrah, and the first caliph after him.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('sahaba-1', 'choice', '{"type":"choice","prompt":"What does \"as-Siddiq\" mean?","options":["The brave","The one who affirms the truth","The generous","The scholar"],"answer":1,"explain":"He earned the title by believing the Prophet ﷺ immediately about the Isra’ and Mi‘raj."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-1', 'truefalse', '{"type":"truefalse","statement":"Abu Bakr freed Bilal from slavery.","answer":true,"explain":"Abu Bakr bought Bilal’s freedom from Umayyah ibn Khalaf."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-1', 'fill', '{"type":"fill","sentence":"Abu Bakr was the ___ caliph of the Muslims.","options":["first","second","third","fourth"],"answer":0,"explain":"The four rightly guided caliphs are Abu Bakr, Umar, Uthman and Ali."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('sahaba-2', 'sahaba', 'Umar ibn al-Khattab', 'Umar was once a fierce enemy of Islam. He accepted Islam after hearing the Quran, became known as al-Faruq, and as the second caliph was famous for his justice.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('sahaba-2', 'choice', '{"type":"choice","prompt":"Which surah was Umar reading when his heart softened?","options":["Al-Fatihah","Ta-Ha","Yasin","Al-Mulk"],"answer":1,"explain":"It was Surah Ta-Ha, at his sister’s house."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-2', 'match', '{"type":"match","prompt":"Match the Companion to his title","pairs":[["Abu Bakr","As-Siddiq"],["Umar","Al-Faruq"],["Uthman","Dhun-Nurayn"]],"explain":"Al-Faruq means the one who distinguishes truth from falsehood."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-2', 'truefalse', '{"type":"truefalse","statement":"Umar was the second caliph.","answer":true,"explain":"He became caliph after Abu Bakr."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('sahaba-3', 'sahaba', 'Uthman and Ali', 'Uthman ibn Affan, the third caliph, was known for his modesty and generosity and gathered the Quran into one standard copy. Ali ibn Abi Talib, the Prophet’s cousin, was the fourth caliph.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('sahaba-3', 'fill', '{"type":"fill","sentence":"Uthman was called Dhun-Nurayn because he married two of the Prophet’s ___.","options":["daughters","cousins","sisters","aunts"],"answer":0,"explain":"He married Ruqayyah and, after her death, Umm Kulthum."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-3', 'choice', '{"type":"choice","prompt":"Who slept in the Prophet’s bed on the night of the Hijrah?","options":["Abu Bakr","Umar","Ali","Bilal"],"answer":2,"explain":"Ali stayed behind and slept in his bed so the Prophet ﷺ could leave safely."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-3', 'order', '{"type":"order","prompt":"Put the four rightly guided caliphs in order","items":["Abu Bakr","Umar","Uthman","Ali"],"explain":"These four led the Muslims after the Prophet ﷺ."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('sahaba-4', 'sahaba', 'Bilal ibn Rabah', 'Bilal was an enslaved man in Makkah who held on to Islam under torture, repeating "Ahad, Ahad" (One, One). He was freed and became the first mu’adhdhin of Islam.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('sahaba-4', 'fill', '{"type":"fill","sentence":"Under torture, Bilal kept saying \"___\", meaning Allah is One.","options":["Ahad, Ahad","Akbar, Akbar","Salam, Salam","Haqq, Haqq"],"answer":0,"explain":"Ahad means One. He refused to give up tawhid."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-4', 'choice', '{"type":"choice","prompt":"What special role did Bilal have in Madinah?","options":["Treasurer","First mu’adhdhin","Army general","Judge"],"answer":1,"explain":"He was the first to call the adhan."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-4', 'truefalse', '{"type":"truefalse","statement":"In Islam, a person is honoured by their lineage more than their taqwa.","answer":false,"explain":"\"The most noble of you in the sight of Allah is the most righteous of you.\"","source":{"kind":"quran","reference":"Quran 49:13"}}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('iman', 'foundations', 'The Articles of Faith', 'Iman and the hadith of Jibril', '#7A4FA3', false, 5) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('iman-1', 'iman', 'Six articles', 'When Jibril asked the Prophet ﷺ about iman, he answered: to believe in Allah, His angels, His books, His messengers, the Last Day, and to believe in the divine decree (qadar), its good and its bad.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('iman-1', 'choice', '{"type":"choice","prompt":"How many articles of faith are mentioned in the hadith of Jibril?","options":["Four","Five","Six","Seven"],"answer":2,"explain":"There are six: Allah, the angels, the books, the messengers, the Last Day, and qadar.","source":{"kind":"hadith","reference":"Sahih Muslim 8"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('iman-1', 'choice', '{"type":"choice","prompt":"Which of these is an article of faith rather than a pillar of Islam?","options":["Fasting","Belief in the angels","Zakat","Hajj"],"answer":1,"explain":"The pillars of Islam are actions. The articles of faith are what a Muslim believes."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('iman-1', 'match', '{"type":"match","prompt":"Match the term to its meaning","pairs":[["Islam","Submission through outward acts"],["Iman","Faith in the heart"],["Ihsan","Worshipping Allah as if you see Him"]],"explain":"The hadith of Jibril teaches all three levels of the religion.","source":{"kind":"hadith","reference":"Sahih Muslim 8"}}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('iman-2', 'iman', 'Books and messengers', 'Allah sent revealed books with His messengers: the Tawrah to Musa, the Zabur to Dawud, the Injil to Isa, and the Quran to Muhammad ﷺ, the final messenger.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('iman-2', 'match', '{"type":"match","prompt":"Match each book to its messenger","pairs":[["Tawrah","Musa"],["Zabur","Dawud"],["Injil","Isa"],["Quran","Muhammad ﷺ"]],"explain":"Belief in all of Allah’s revealed books is part of iman."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('iman-2', 'choice', '{"type":"choice","prompt":"Which angel brought revelation to the prophets?","options":["Mika’il","Jibril","Malik","Ridwan"],"answer":1,"explain":"Jibril brought the revelation, and is described in the Quran as the trustworthy spirit (26:193).","source":{"kind":"quran","reference":"Quran 26:193"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('iman-2', 'choice', '{"type":"choice","minLevel":"advanced","prompt":"What does \"khatam an-nabiyyin\" in Al-Ahzab 33:40 mean?","options":["The first of the prophets","The seal of the prophets","The friend of the prophets","The son of the prophets"],"answer":1,"explain":"Muhammad ﷺ is the seal of the prophets: no prophet comes after him.","source":{"kind":"quran","reference":"Quran 33:40"}}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('madhabs', 'foundations', 'Prayer in the Four Madhabs', 'Where the schools agree and differ', '#A35A2E', false, 6) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('madhabs-1', 'madhabs', 'The four schools', 'The four Sunni schools of fiqh are named after Imam Abu Hanifah, Imam Malik, Imam ash-Shafi‘i and Imam Ahmad ibn Hanbal. They agree on the foundations and differ in some details, each with evidence. Follow a qualified teacher in your school.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('madhabs-1', 'match', '{"type":"match","prompt":"Match each school to its founding imam","pairs":[["Hanafi","Abu Hanifah"],["Maliki","Malik ibn Anas"],["Shafi‘i","Muhammad ibn Idris ash-Shafi‘i"],["Hanbali","Ahmad ibn Hanbal"]],"explain":"All four are respected schools of Sunni fiqh."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('madhabs-1', 'choice', '{"type":"choice","prompt":"Which school treats witr as wajib (necessary) rather than sunnah?","options":["Hanafi","Maliki","Shafi‘i","Hanbali"],"answer":0,"explain":"The Hanafi school holds witr to be wajib. The other three hold it to be a highly stressed sunnah."}'::jsonb, 2);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('madhabs-2', 'madhabs', 'Asr time and raising the hands', 'For Asr, the Hanafi school begins the time when an object’s shadow is twice its length, while the other three schools begin it when the shadow equals its length. On raising the hands at ruku‘, the Shafi‘i and Hanbali schools do it, while the Hanafi school, and the Maliki school in its well-known view, raise them only at the opening takbir.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('madhabs-2', 'choice', '{"type":"choice","prompt":"In the Hanafi school, Asr begins when a shadow is…","options":["Equal to the object","Twice the object","Half the object","Gone"],"answer":1,"explain":"This is why prayer apps offer a separate Hanafi Asr setting."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('madhabs-2', 'match', '{"type":"match","prompt":"Raising the hands when going into ruku‘","pairs":[["Shafi‘i","Raises the hands"],["Hanbali","Also raises the hands"],["Hanafi","Only at the opening takbir"]],"explain":"Both practices have evidence in the Sunnah. Each school weighed the narrations differently."}'::jsonb, 2);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('arabic-letters', 'foundations', 'The letters', 'All 28 letters, a few at a time', '#2E6FA3', true, 7) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-1', 'arabic-letters', 'Alif, Ba, Ta, Tha', 'Arabic is read from right to left. Ba, Ta and Tha share one shape, a little boat. Only the dots change: one below, two above, three above.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-1', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ا","options":["Ba","Alif","Ta","Tha"],"answer":1,"explain":"This is Alif. Carries a long “aa” sound, or holds a hamza."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-1', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ب","options":["Ta","Tha","Ba","Jim"],"answer":2,"explain":"This is Ba. “b” as in bat. One dot below."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-1', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ت","options":["Tha","Jim","Ḥa (throat h)","Ta"],"answer":3,"explain":"This is Ta. “t” as in tea. Two dots above."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-1', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ث","options":["Tha","Jim","Ḥa (throat h)","Kha"],"answer":0,"explain":"This is Tha. “th” as in think. Three dots above."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-1', 'choice', '{"type":"choice","prompt":"Tap Alif","options":["ث","ج","ا","ح"],"answer":2,"explain":"ا is Alif. Carries a long “aa” sound, or holds a hamza."}'::jsonb, 5);
insert into exercises (lesson_id, type, body, sort) values ('arabic-1', 'choice', '{"type":"choice","prompt":"Tap Ba","options":["ج","ح","خ","ب"],"answer":3,"explain":"ب is Ba. “b” as in bat. One dot below."}'::jsonb, 6);
insert into exercises (lesson_id, type, body, sort) values ('arabic-1', 'match', '{"type":"match","prompt":"Match each letter to its sound","pairs":[["ا","aa (long a)"],["ب","b"],["ت","t"],["ث","th (think)"]],"explain":"ا Alif: aa (long a) · ب Ba: b · ت Ta: t · ث Tha: th (think)"}'::jsonb, 7);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-2', 'arabic-letters', 'Jim, Ḥa, Kha', 'These three share a hook shape. Jim has a dot inside, Ḥa has none, and Kha has a dot on top.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-2', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ج","options":["Kha","Jim","Alif","Ba"],"answer":1,"explain":"This is Jim. “j” as in jam. One dot inside."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-2', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ح","options":["Alif","Ba","Ḥa (throat h)","Ta"],"answer":2,"explain":"This is Ḥa (throat h). A breathy “h” from the middle of the throat. No dots."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-2', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"خ","options":["Ba","Ta","Tha","Kha"],"answer":3,"explain":"This is Kha. “kh” like clearing your throat, as in Scottish loch. One dot above."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-2', 'choice', '{"type":"choice","prompt":"Tap Jim","options":["ا","ب","ج","ت"],"answer":2,"explain":"ج is Jim. “j” as in jam. One dot inside."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-2', 'choice', '{"type":"choice","prompt":"Tap Ḥa (throat h)","options":["ب","ت","ث","ح"],"answer":3,"explain":"ح is Ḥa (throat h). A breathy “h” from the middle of the throat. No dots."}'::jsonb, 5);
insert into exercises (lesson_id, type, body, sort) values ('arabic-2', 'match', '{"type":"match","prompt":"Match each letter to its sound","pairs":[["ج","j"],["ح","ḥ (throat)"],["خ","kh"]],"explain":"ج Jim: j · ح Ḥa (throat h): ḥ (throat) · خ Kha: kh"}'::jsonb, 6);
insert into exercises (lesson_id, type, body, sort) values ('arabic-2', 'choice', '{"type":"choice","prompt":"Review: what sound does this letter make?","picture":"ث","options":["b","th (think)","t","j"],"answer":1,"explain":"ث is Tha. “th” as in think. Three dots above."}'::jsonb, 7);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-3', 'arabic-letters', 'Dal, Dhal, Ra, Zay', 'Dal and Dhal are short corners; Ra and Zay dip below the line. The dot turns Dal into Dhal and Ra into Zay.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-3', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"د","options":["Zay","Dal","Alif","Ba"],"answer":1,"explain":"This is Dal. “d” as in door."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-3', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ذ","options":["Alif","Ba","Dhal","Ta"],"answer":2,"explain":"This is Dhal. “th” as in this. One dot above."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-3', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ر","options":["Ba","Ta","Tha","Ra"],"answer":3,"explain":"This is Ra. A lightly rolled “r”."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-3', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ز","options":["Zay","Ta","Tha","Jim"],"answer":0,"explain":"This is Zay. “z” as in zoo. One dot above."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-3', 'choice', '{"type":"choice","prompt":"Tap Dal","options":["ز","ا","د","ب"],"answer":2,"explain":"د is Dal. “d” as in door."}'::jsonb, 5);
insert into exercises (lesson_id, type, body, sort) values ('arabic-3', 'choice', '{"type":"choice","prompt":"Tap Dhal","options":["ا","ب","ت","ذ"],"answer":3,"explain":"ذ is Dhal. “th” as in this. One dot above."}'::jsonb, 6);
insert into exercises (lesson_id, type, body, sort) values ('arabic-3', 'match', '{"type":"match","prompt":"Match each letter to its sound","pairs":[["د","d"],["ذ","dh (this)"],["ر","r"],["ز","z"]],"explain":"د Dal: d · ذ Dhal: dh (this) · ر Ra: r · ز Zay: z"}'::jsonb, 7);
insert into exercises (lesson_id, type, body, sort) values ('arabic-3', 'choice', '{"type":"choice","prompt":"Review: what sound does this letter make?","picture":"خ","options":["t","th (think)","kh","j"],"answer":2,"explain":"خ is Kha. “kh” like clearing your throat, as in Scottish loch. One dot above."}'::jsonb, 8);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-4', 'arabic-letters', 'Sin, Shin, Ṣad, Ḍad', 'Sin has three little teeth; three dots make it Shin. Ṣad and Ḍad have a loop and are heavy letters, said with a full mouth.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-4', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"س","options":["Alif","Sin","Ba","Ta"],"answer":1,"explain":"This is Sin. “s” as in sun. Three little teeth."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-4', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ش","options":["Ba","Ta","Shin","Tha"],"answer":2,"explain":"This is Shin. “sh” as in shoe. Teeth with three dots."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-4', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ص","options":["Ta","Tha","Jim","Ṣad (heavy s)"],"answer":3,"explain":"This is Ṣad (heavy s). A heavy “s” said with a full, rounded mouth."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-4', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ض","options":["Ḍad (heavy d)","Tha","Jim","Ḥa (throat h)"],"answer":0,"explain":"This is Ḍad (heavy d). A heavy “d” from the side of the tongue. One dot above."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-4', 'choice', '{"type":"choice","prompt":"Tap Sin","options":["ض","ا","س","ب"],"answer":2,"explain":"س is Sin. “s” as in sun. Three little teeth."}'::jsonb, 5);
insert into exercises (lesson_id, type, body, sort) values ('arabic-4', 'choice', '{"type":"choice","prompt":"Tap Shin","options":["ا","ب","ت","ش"],"answer":3,"explain":"ش is Shin. “sh” as in shoe. Teeth with three dots."}'::jsonb, 6);
insert into exercises (lesson_id, type, body, sort) values ('arabic-4', 'match', '{"type":"match","prompt":"Match each letter to its sound","pairs":[["س","s"],["ش","sh"],["ص","ṣ (heavy s)"],["ض","ḍ (heavy d)"]],"explain":"س Sin: s · ش Shin: sh · ص Ṣad (heavy s): ṣ (heavy s) · ض Ḍad (heavy d): ḍ (heavy d)"}'::jsonb, 7);
insert into exercises (lesson_id, type, body, sort) values ('arabic-4', 'choice', '{"type":"choice","prompt":"Review: what sound does this letter make?","picture":"ر","options":["th (think)","j","ḥ (throat)","r"],"answer":3,"explain":"ر is Ra. A lightly rolled “r”."}'::jsonb, 8);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-5', 'arabic-letters', 'Ṭa, Ẓa, ʿAyn, Ghayn', 'Ṭa and Ẓa are heavy letters with a tall stick. ʿAyn and Ghayn come from the throat. A dot turns ʿAyn into Ghayn.', 5, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-5', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ط","options":["Ba","Ṭa (heavy t)","Ta","Tha"],"answer":1,"explain":"This is Ṭa (heavy t). A heavy “t” with a full mouth."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-5', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ظ","options":["Ta","Tha","Ẓa (heavy dh)","Jim"],"answer":2,"explain":"This is Ẓa (heavy dh). A heavy “th” as in this. One dot above."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-5', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ع","options":["Tha","Jim","Ḥa (throat h)","ʿAyn"],"answer":3,"explain":"This is ʿAyn. A tight sound from deep in the throat. There is no English match, so listen to a reciter."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-5', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"غ","options":["Ghayn","Jim","Ḥa (throat h)","Kha"],"answer":0,"explain":"This is Ghayn. “gh”, like gargling or a French “r”. One dot above."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-5', 'choice', '{"type":"choice","prompt":"Tap Ṭa (heavy t)","options":["غ","ا","ط","ب"],"answer":2,"explain":"ط is Ṭa (heavy t). A heavy “t” with a full mouth."}'::jsonb, 5);
insert into exercises (lesson_id, type, body, sort) values ('arabic-5', 'choice', '{"type":"choice","prompt":"Tap Ẓa (heavy dh)","options":["ا","ب","ت","ظ"],"answer":3,"explain":"ظ is Ẓa (heavy dh). A heavy “th” as in this. One dot above."}'::jsonb, 6);
insert into exercises (lesson_id, type, body, sort) values ('arabic-5', 'match', '{"type":"match","prompt":"Match each letter to its sound","pairs":[["ط","ṭ (heavy t)"],["ظ","ẓ (heavy dh)"],["ع","ʿ (deep throat)"],["غ","gh"]],"explain":"ط Ṭa (heavy t): ṭ (heavy t) · ظ Ẓa (heavy dh): ẓ (heavy dh) · ع ʿAyn: ʿ (deep throat) · غ Ghayn: gh"}'::jsonb, 7);
insert into exercises (lesson_id, type, body, sort) values ('arabic-5', 'choice', '{"type":"choice","prompt":"Review: what sound does this letter make?","picture":"ش","options":["sh","j","ḥ (throat)","kh"],"answer":0,"explain":"ش is Shin. “sh” as in shoe. Teeth with three dots."}'::jsonb, 8);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-6', 'arabic-letters', 'Fa, Qaf, Kaf, Lam', 'Fa has one dot and Qaf has two, and Qaf dips lower. Kaf has a little mark inside. Lam is tall like a hook.', 6, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-6', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ف","options":["Ta","Fa","Tha","Jim"],"answer":1,"explain":"This is Fa. “f” as in fish. One dot above."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-6', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ق","options":["Tha","Jim","Qaf","Ḥa (throat h)"],"answer":2,"explain":"This is Qaf. A deep “k” from the very back of the throat. Two dots above."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-6', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ك","options":["Jim","Ḥa (throat h)","Kha","Kaf"],"answer":3,"explain":"This is Kaf. “k” as in kite."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-6', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ل","options":["Lam","Ḥa (throat h)","Kha","Dal"],"answer":0,"explain":"This is Lam. “l” as in lamp."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-6', 'choice', '{"type":"choice","prompt":"Tap Fa","options":["ل","ا","ف","ب"],"answer":2,"explain":"ف is Fa. “f” as in fish. One dot above."}'::jsonb, 5);
insert into exercises (lesson_id, type, body, sort) values ('arabic-6', 'choice', '{"type":"choice","prompt":"Tap Qaf","options":["ا","ب","ت","ق"],"answer":3,"explain":"ق is Qaf. A deep “k” from the very back of the throat. Two dots above."}'::jsonb, 6);
insert into exercises (lesson_id, type, body, sort) values ('arabic-6', 'match', '{"type":"match","prompt":"Match each letter to its sound","pairs":[["ف","f"],["ق","q (deep k)"],["ك","k"],["ل","l"]],"explain":"ف Fa: f · ق Qaf: q (deep k) · ك Kaf: k · ل Lam: l"}'::jsonb, 7);
insert into exercises (lesson_id, type, body, sort) values ('arabic-6', 'choice', '{"type":"choice","prompt":"Review: what sound does this letter make?","picture":"ط","options":["ḥ (throat)","ṭ (heavy t)","kh","d"],"answer":1,"explain":"ط is Ṭa (heavy t). A heavy “t” with a full mouth."}'::jsonb, 8);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-7', 'arabic-letters', 'Mim, Nun, Ha, Waw, Ya', 'The last five. Mim is a small circle with a tail, Nun a bowl with a dot, Ha a soft loop. Waw and Ya can also stretch a vowel long.', 7, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"م","options":["Ta","Mim","Tha","Jim"],"answer":1,"explain":"This is Mim. “m” as in moon."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ن","options":["Tha","Jim","Nun","Ḥa (throat h)"],"answer":2,"explain":"This is Nun. “n” as in noon. One dot above."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ه","options":["Jim","Ḥa (throat h)","Kha","Ha (soft h)"],"answer":3,"explain":"This is Ha (soft h). A soft “h” as in hat."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"و","options":["Waw","Ḥa (throat h)","Kha","Dal"],"answer":0,"explain":"This is Waw. “w” as in water, or a long “uu”."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'choice', '{"type":"choice","prompt":"Which letter is this?","picture":"ي","options":["Kha","Ya","Dal","Dhal"],"answer":1,"explain":"This is Ya. “y” as in yes, or a long “ii”. Two dots below."}'::jsonb, 5);
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'choice', '{"type":"choice","prompt":"Tap Mim","options":["و","ي","م","ا"],"answer":2,"explain":"م is Mim. “m” as in moon."}'::jsonb, 6);
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'choice', '{"type":"choice","prompt":"Tap Nun","options":["ي","ا","ب","ن"],"answer":3,"explain":"ن is Nun. “n” as in noon. One dot above."}'::jsonb, 7);
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'match', '{"type":"match","prompt":"Match each letter to its sound","pairs":[["م","m"],["ن","n"],["ه","h"],["و","w"]],"explain":"م Mim: m · ن Nun: n · ه Ha (soft h): h · و Waw: w · ي Ya: y"}'::jsonb, 8);
insert into exercises (lesson_id, type, body, sort) values ('arabic-7', 'choice', '{"type":"choice","prompt":"Review: what sound does this letter make?","picture":"غ","options":["kh","d","gh","dh (this)"],"answer":2,"explain":"غ is Ghayn. “gh”, like gargling or a French “r”. One dot above."}'::jsonb, 9);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('arabic-marks', 'foundations', 'Joining and vowels', 'The marks that make letters speak', '#7A5BA6', true, 8) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-8', 'arabic-marks', 'Letters hold hands', 'In a word, most letters join to the next one and change shape a little: they lose their tail. Six letters never join to the letter after them: ا د ذ ر ز و. After one of these, the next letter starts fresh.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-8', 'choice', '{"type":"choice","prompt":"Which of these letters never joins to the letter after it?","options":["ب","د","م","ك"],"answer":1,"explain":"Dal never joins forward. The six that never do are ا د ذ ر ز و."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-8', 'choice', '{"type":"choice","prompt":"Which one is Ba at the start of a word?","options":["ـب","بـ","ـبـ"],"answer":1,"explain":"At the start, Ba loses its tail and reaches forward to join the next letter: بـ"}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-8', 'choice', '{"type":"choice","prompt":"Which one is Ba at the end of a word?","options":["ـبـ","بـ","ـب"],"answer":2,"explain":"At the end, Ba keeps its tail: ـب"}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-8', 'truefalse', '{"type":"truefalse","statement":"Arabic is read from right to left.","answer":true,"explain":"Yes. Start on the right and move left, for the Quran and all Arabic writing."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-8', 'choice', '{"type":"choice","prompt":"Which letter is this, joined at the start of a word?","options":["Mim","Nun","Ya","Ba"],"answer":2,"explain":"Ya at the start of a word keeps its two dots below: يـ","picture":"يـ"}'::jsonb, 5);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-9', 'arabic-marks', 'The short vowels', 'Little marks above or below a letter tell you the vowel. Fatha is a small line above and says “a”. Kasra is a small line below and says “i”. Damma is a small curl above and says “u”.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-9', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["ba","bi","bu"],"answer":1,"explain":"The line below is a kasra, so it says “bi”.","picture":"بِ"}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-9', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["ka","ki","ku"],"answer":2,"explain":"The curl above is a damma, so it says “ku”.","picture":"كُ"}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-9', 'choice', '{"type":"choice","prompt":"Which mark says “a”?","options":["A small line below (kasra)","A small line above (fatha)","A small curl above (damma)"],"answer":1,"explain":"Fatha is the small line above, and says “a”."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-9', 'match', '{"type":"match","prompt":"Match each one to how it is read","pairs":[["لَ","la"],["مِ","mi"],["نُ","nu"],["سَ","sa"]],"explain":"Fatha says a, kasra says i, damma says u."}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('arabic-9', 'choice', '{"type":"choice","prompt":"How do you read this word?","options":["kataba","kutiba","kitab"],"answer":0,"explain":"Every letter has a fatha: ka-ta-ba. It means “he wrote”.","picture":"كَتَبَ"}'::jsonb, 5);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-10', 'arabic-marks', 'Sukun and shadda', 'A small circle (sukun) means the letter has no vowel: you stop on it, like the “l” in قُلْ “qul”. A small “w” shape (shadda) means the letter is said twice, like رَبّ “rabb”.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-10', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["mina","min","mun"],"answer":1,"explain":"Kasra on mim, sukun on nun: “min”. It means “from”.","picture":"مِنْ"}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-10', 'choice', '{"type":"choice","prompt":"What does a shadda do?","options":["Makes the letter silent","Says the letter twice","Makes a long vowel"],"answer":1,"explain":"Shadda doubles the letter, so you hold it a little longer."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-10', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["thuma","thumma","thamma"],"answer":1,"explain":"Damma on tha, shadda and fatha on mim: “thumma”. It means “then”.","picture":"ثُمَّ"}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-10', 'match', '{"type":"match","prompt":"Match each word to how it is read","pairs":[["قُلْ","qul"],["لَمْ","lam"],["إِنَّ","inna"],["رَبِّ","rabbi"]],"explain":"Sukun stops the letter; shadda doubles it."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-11', 'arabic-marks', 'Tanween', 'When a vowel mark is written twice, it adds an “n” sound at the end of a word. This is tanween: بً “ban”, بٍ “bin”, بٌ “bun”.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-11', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["ba","ban","bun"],"answer":2,"explain":"Two dammas say “un”, so it reads “bun”.","picture":"بٌ"}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-11', 'choice', '{"type":"choice","prompt":"How do you read the end of this word?","options":["ahada","ahadun","ahadin"],"answer":1,"explain":"Two dammas on the last letter: a-ha-dun. From Surah Al-Ikhlas: “One”.","picture":"أَحَدٌ"}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-11', 'match', '{"type":"match","prompt":"Match each one to how it is read","pairs":[["كً","kan"],["مٍ","min"],["نٌ","nun"]],"explain":"Double fatha = an, double kasra = in, double damma = un."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-11', 'truefalse', '{"type":"truefalse","statement":"Tanween adds an “n” sound to the end of a word.","answer":true,"explain":"Yes. A doubled vowel mark adds “n”."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-12', 'arabic-marks', 'Long vowels', 'Alif, Waw and Ya stretch a vowel to twice its length. Fatha then Alif makes a long “aa”, damma then Waw a long “uu”, kasra then Ya a long “ii”.', 5, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-12', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["nur","nuur","nar"],"answer":1,"explain":"Damma then Waw makes a long “uu”: nuur. It means “light”.","picture":"نُور"}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-12', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["qaala","qala","qiila"],"answer":0,"explain":"Fatha then Alif makes a long “aa”: qaa-la. It means “he said”.","picture":"قَالَ"}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-12', 'choice', '{"type":"choice","prompt":"Which letter stretches a kasra into a long “ii”?","options":["Alif","Waw","Ya"],"answer":2,"explain":"Kasra followed by Ya gives a long “ii”, as in دِين “diin”."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-12', 'match', '{"type":"match","prompt":"Match each word to how it is read","pairs":[["دِين","diin"],["نُور","nuur"],["بَاب","baab"]],"explain":"Alif, Waw and Ya make the vowel long."}'::jsonb, 4);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('arabic-words', 'foundations', 'Reading the Quran', 'Your first words from the Quran', '#2F7D5B', true, 9) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-13', 'arabic-words', 'Words of Al-Fatiha', 'Now put it together. These words open the Quran. Read them slowly, letter by letter, then listen to them in the Quran tab to hear them recited.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-13', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["bismi","basama","bisam"],"answer":0,"explain":"Kasra on ba, sukun on sin, kasra on mim: bis-mi.","picture":"بِسْمِ"}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-13', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["al-hamdu","al-hamad","al-hamida"],"answer":0,"explain":"Al, then ha with fatha, mim with sukun, dal with damma: al-ham-du.","picture":"الْحَمْدُ"}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-13', 'match', '{"type":"match","prompt":"Match each word to its meaning","pairs":[["بِسْمِ","In the name of"],["الْحَمْدُ","All praise"],["رَبِّ","Lord of"],["الرَّحِيمِ","The Most Merciful"]],"explain":"From Surah Al-Fatiha, 1:1 to 1:3.","source":{"kind":"quran","reference":"Quran 1:1–3"}}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-13', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["ar-rahimi","ar-rahmi","ar-ruhumi"],"answer":0,"explain":"The ra has a shadda, so the lam is not said: ar-ra-hii-mi.","picture":"الرَّحِيمِ"}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('arabic-14', 'arabic-words', 'Words of Al-Ikhlas', 'Surah Al-Ikhlas is short and loved. You already know every letter and mark in it. Read each word, then try the whole surah in the Quran tab.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('arabic-14', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["huwa","hawa","hiya"],"answer":0,"explain":"Damma on ha, fatha on waw: hu-wa. It means “He”.","picture":"هُوَ"}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('arabic-14', 'choice', '{"type":"choice","prompt":"How do you read this?","options":["yalid","yuladu","walad"],"answer":0,"explain":"Fatha on ya, kasra on lam, sukun on dal: ya-lid. “He did not beget.”","picture":"يَلِدْ"}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('arabic-14', 'match', '{"type":"match","prompt":"Match each word to its meaning","pairs":[["قُلْ","Say"],["أَحَدٌ","One"],["الصَّمَدُ","The Eternal Refuge"]],"explain":"From Surah Al-Ikhlas.","source":{"kind":"quran","reference":"Quran 112:1–2"}}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('arabic-14', 'order', '{"type":"order","prompt":"Tap the words of the first ayah in order","items":["قُلْ","هُوَ","اللَّهُ","أَحَدٌ"],"explain":"قُلْ هُوَ اللَّهُ أَحَدٌ: “Say: He is Allah, One.”","source":{"kind":"quran","reference":"Quran 112:1"}}'::jsonb, 4);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('kids-allah', 'foundations', 'Allah made everything', 'Who made the sun, the sea and you?', '#2F7D5B', true, 10) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-allah-1', 'kids-allah', 'Our Creator', 'Allah made everything: the sun, the moon, the trees, the animals and you! Allah is One, and there is nothing like Him.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-allah-1', 'choice', '{"type":"choice","prompt":"Who made the sun?","picture":"☀️","options":["Allah","People","Nobody"],"answer":0,"explain":"Allah made the sun and everything else.","source":{"kind":"quran","reference":"Quran 39:62"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-allah-1', 'truefalse', '{"type":"truefalse","statement":"Allah is One.","picture":"☝️","answer":true,"explain":"Yes! “Say: He is Allah, One.”","source":{"kind":"quran","reference":"Quran 112:1"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('kids-allah-1', 'choice', '{"type":"choice","prompt":"What do we say when we see something beautiful?","picture":"🌈","options":["SubhanAllah","Goodbye","Oops"],"answer":0,"explain":"SubhanAllah means “Glory be to Allah”. We say it when we see how amazing Allah’s creation is."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-allah-2', 'kids-allah', 'Allah is Ar-Rahman', 'Allah has beautiful names. Ar-Rahman means the Most Merciful. Allah gives us food, water, our family and so much more.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-allah-2', 'choice', '{"type":"choice","prompt":"What does Ar-Rahman mean?","picture":"💚","options":["The Most Merciful","The Strongest Lion","The Big Sky"],"answer":0,"explain":"Ar-Rahman is one of Allah’s beautiful names. It means the Most Merciful."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-allah-2', 'choice', '{"type":"choice","prompt":"Who gives us water to drink?","picture":"💧","options":["Allah","The cat","The moon"],"answer":0,"explain":"Allah sends the rain and gives us water."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('kids-allah-2', 'truefalse', '{"type":"truefalse","statement":"We say “Alhamdulillah” to thank Allah.","picture":"🤲","answer":true,"explain":"Yes! Alhamdulillah means “All praise is for Allah”."}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('kids-words', 'foundations', 'Little words, big reward', 'Special words Muslims say every day', '#E2A93B', true, 11) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-words-1', 'kids-words', 'Bismillah', 'Before we eat, we say “Bismillah”, which means “In the name of Allah”. When we finish, we say “Alhamdulillah”.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-words-1', 'choice', '{"type":"choice","prompt":"What do we say before we eat?","picture":"🍽️","options":["Bismillah","Goodnight","Hooray"],"answer":0,"explain":"The Prophet ﷺ taught us to say Bismillah before eating.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 5376"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-words-1', 'choice', '{"type":"choice","prompt":"What do we say when we finish eating?","picture":"😋","options":["Alhamdulillah","Bismillah","Ameen"],"answer":0,"explain":"We thank Allah for the food by saying Alhamdulillah."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('kids-words-1', 'match', '{"type":"match","prompt":"Match the words","pairs":[["Bismillah","In the name of Allah"],["Alhamdulillah","All praise is for Allah"]],"explain":"Great job! Two words that bring big reward."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-words-2', 'kids-words', 'Assalamu alaikum', 'When Muslims meet, we say “Assalamu alaikum”, which means “Peace be upon you”. We answer “Wa alaikum assalam”.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-words-2', 'choice', '{"type":"choice","prompt":"Your friend says “Assalamu alaikum”. What do you say back?","picture":"👋","options":["Wa alaikum assalam","Bismillah","Bye"],"answer":0,"explain":"We answer with “Wa alaikum assalam”, peace be upon you too."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-words-2', 'truefalse', '{"type":"truefalse","statement":"“Assalamu alaikum” means “Peace be upon you”.","picture":"🕊️","answer":true,"explain":"Yes! Spreading salam spreads peace."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('kids-words-2', 'choice', '{"type":"choice","prompt":"What do we say when someone gives us a gift?","picture":"🎁","options":["JazakAllahu khayran","Oops","SubhanAllah"],"answer":0,"explain":"JazakAllahu khayran means “May Allah reward you with good”. It is a lovely way to say thank you."}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('kids-pillars', 'foundations', 'My five pillars', 'Five things that hold up Islam', '#2E6FA3', true, 12) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-pillars-1', 'kids-pillars', 'Five pillars', 'A house stands on pillars. Islam stands on five: saying the Shahada, praying, giving to people in need, fasting in Ramadan and going to Hajj.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-pillars-1', 'choice', '{"type":"choice","prompt":"How many pillars does Islam have?","picture":"🏛️","options":["5","2","10"],"answer":0,"explain":"Islam is built on five pillars.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-pillars-1', 'choice', '{"type":"choice","prompt":"Which pillar is this?","picture":"🌙","options":["Fasting in Ramadan","Hajj","Zakat"],"answer":0,"explain":"In Ramadan, grown-ups fast from dawn until sunset."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('kids-pillars-1', 'choice', '{"type":"choice","prompt":"How many times a day do Muslims pray?","picture":"🕌","options":["5","1","3"],"answer":0,"explain":"Fajr, Dhuhr, Asr, Maghrib and Isha. Five prayers every day!"}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-pillars-2', 'kids-pillars', 'Getting ready to pray', 'Before we pray, we make wudu: we wash with water to be clean. Start with Bismillah, wash your hands, mouth, nose, face, arms, wipe your head and ears, then wash your feet.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-pillars-2', 'choice', '{"type":"choice","prompt":"What do we do before we pray?","picture":"💧","options":["Make wudu","Eat a snack","Go to sleep"],"answer":0,"explain":"Wudu makes us clean and ready to stand before Allah."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-pillars-2', 'order', '{"type":"order","prompt":"Put the wudu steps in order","items":["🙌 Hands","🙂 Face","💪 Arms","🦶 Feet"],"explain":"Hands, then mouth and nose, face, arms, head and ears, and feet last.","source":{"kind":"quran","reference":"Quran 5:6"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('kids-pillars-2', 'truefalse', '{"type":"truefalse","statement":"We wash our feet last in wudu.","picture":"🦶","answer":true,"explain":"Yes! Feet come at the end."}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('kids-manners', 'foundations', 'Kind like the Prophet ﷺ', 'Good manners make Allah happy', '#C8553D', true, 13) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-manners-1', 'kids-manners', 'A smile is charity', 'The Prophet ﷺ said that smiling at your brother or sister is a charity. Being kind, sharing and helping your parents all bring reward.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-manners-1', 'truefalse', '{"type":"truefalse","statement":"Smiling at someone is a kind of charity.","picture":"😊","answer":true,"explain":"Yes! The Prophet ﷺ said your smile for your brother is charity.","source":{"kind":"hadith","reference":"Jami at-Tirmidhi 1956"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-manners-1', 'choice', '{"type":"choice","prompt":"Your friend has no toy to play with. What do you do?","picture":"🧸","options":["Share with them","Hide my toys","Laugh at them"],"answer":0,"explain":"Sharing is kind, and Allah loves people who are kind."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('kids-manners-1', 'choice', '{"type":"choice","prompt":"Mum is carrying lots of bags. What do you do?","picture":"🛍️","options":["Help her carry them","Keep playing","Run away"],"answer":0,"explain":"Being good to our parents is one of the best deeds."}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('kids-prophets', 'foundations', 'Prophets we love', 'Short stories from the Quran', '#7A5BA6', true, 14) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-prophets-1', 'kids-prophets', 'Nuh and the ark', 'Prophet Nuh (peace be upon him) told his people to worship Allah. Allah told him to build a big ark. When the great flood came, the believers and the animals were safe inside.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-prophets-1', 'choice', '{"type":"choice","prompt":"What did Prophet Nuh build?","picture":"🚢","options":["An ark","A tower","A castle"],"answer":0,"explain":"Allah told Nuh to build an ark to keep the believers safe.","source":{"kind":"quran","reference":"Quran 11:37"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-prophets-1', 'truefalse', '{"type":"truefalse","statement":"The animals came onto the ark in pairs.","picture":"🦒","answer":true,"explain":"Yes! Allah told Nuh to carry a pair of every kind.","source":{"kind":"quran","reference":"Quran 11:40"}}'::jsonb, 2);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('kids-prophets-2', 'kids-prophets', 'Yunus and the whale', 'Prophet Yunus (peace be upon him) was swallowed by a big fish. In the dark he prayed: “There is no god but You, glory be to You.” Allah heard him and saved him.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('kids-prophets-2', 'choice', '{"type":"choice","prompt":"Who swallowed Prophet Yunus?","picture":"🐋","options":["A big fish","A lion","A bird"],"answer":0,"explain":"A big fish swallowed Yunus, and he prayed to Allah from inside it.","source":{"kind":"quran","reference":"Quran 37:142"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('kids-prophets-2', 'truefalse', '{"type":"truefalse","statement":"Allah heard Yunus when he prayed in the dark.","picture":"🤲","answer":true,"explain":"Yes! Allah always hears our dua, wherever we are.","source":{"kind":"quran","reference":"Quran 21:87–88"}}'::jsonb, 2);
